from collections import deque
def pockets(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==0 and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==0 and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w and g[rr][cc]==0 and not seen[rr][cc]:
                seen[rr][cc]=True; q.append((rr,cc))
    return [(r,c) for r in range(h) for c in range(w) if g[r][c]==0 and not seen[r][c]]
