def conn_border(p):
    q=deque([p]); seen={p}
    while q:
        a,b=q.popleft()
        if a in (0,H-1) or b in (0,W-1): return True
        for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
            x,y=a+di,b+dj
            if 0<=x<H and 0<=y<W and I[x,y]==0 and (x,y) not in seen:
                seen.add((x,y)); q.append((x,y))
    return False
